    N = int(input_data[0]); K = int(input_data[1])
    if N == 0:
        print(); return
    arr = [int(input_data[2 + i]) for i in range(N)]

    heap = []
    res = []
    for i in range(min(K + 1, N)):
        heapq.heappush(heap, arr[i])

    for i in range(K + 1, N):
        res.append(heapq.heappop(heap))
        heapq.heappush(heap, arr[i])

    while heap:
        res.append(heapq.heappop(heap))

