from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data: return
    Q = int(input_data[0])
    idx = 1
    dq = deque()
    reversed_state = False
    out = []
    for _ in range(Q):
        op = int(input_data[idx]); idx += 1
        if op == 1:
            reversed_state = not reversed_state
        elif op == 2:
            val = input_data[idx]; idx += 1
            if not reversed_state: dq.append(val)
            else: dq.appendleft(val)
        elif op == 3:
            if not dq:
                out.append('EMPTY')
            else:
                if not reversed_state: out.append(dq.popleft())
                else: out.append(dq.pop())
    if out:
        print('\n'.join(out))

if __name__ == '__main__':
