            int op = Integer.parseInt(st.nextToken());
            if (op == 1) rev = !rev;
            else if (op == 2) {
                String val = st.nextToken();
                if (!rev) dq.addLast(val);
                else dq.addFirst(val);
            } else {
                if (dq.isEmpty()) sb.append("EMPTY\n");
                else {
                    if (!rev) sb.append(dq.pollFirst()).append('\n');
                    else sb.append(dq.pollLast()).append('\n');
                }
            }
        }
        System.out.print(sb);
    }
}

