        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int m = Integer.parseInt(st.nextToken());
            if (m > 0) {
                int[] row = new int[m];
                for (int j = 0; j < m; j++) row[j] = Integer.parseInt(st.nextToken());
                lists.add(row);
                pq.add(new Item(row[0], lists.size() - 1, 0));
            }
        }
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        while (!pq.isEmpty()) {
            Item item = pq.poll();
            if (!first) sb.append(' ');
            sb.append(item.val);
